@Override
    public void render(ScytheBoomerang entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        poseStack.pushPose();
        var stack = entityIn.getItem();
        var model = this.itemRenderer.getModel(stack, entityIn.level(), null, 1);
        if (entityIn.isNarrow()) {
            Vec3 direction = entityIn.getDeltaMovement().normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z)));
            poseStack.mulPose(Axis.YP.rotation(yRot+1.57f));
        }
        else {
            poseStack.mulPose(Axis.XP.rotationDegrees(90f));
        }
        poseStack.mulPose(Axis.ZP.rotation((entityIn.age + partialTicks) * 0.9f));
        poseStack.scale(2f, 2, 1.5f);
        itemRenderer.render(stack, stack.getItem() instanceof MalumScytheItem ? ItemDisplayContext.NONE : ItemDisplayContext.FIXED, false, poseStack, bufferIn, packedLightIn, OverlayTexture.NO_OVERLAY, model);
        poseStack.popPose();

        var spirit = stack.getItem() instanceof ISpiritAffiliatedItem affiliatedItem ? affiliatedItem.getDefiningSpiritType(stack) : null;
        boolean isMagical = spirit != null;
        var renderType = isMagical ?
                LodestoneRenderTypes.ADDITIVE_TWO_SIDED_TEXTURE_TRIANGLE.apply(MalumRenderTypeTokens.CONCENTRATED_TRAIL) :
                LodestoneRenderTypes.TRANSPARENT_TWO_SIDED_TEXTURE_TRIANGLE.apply(MalumRenderTypeTokens.CONCENTRATED_TRAIL).addUniformData(UniformData.LUMITRANSPARENT);
        var primaryColor = isMagical ? spirit.getPrimaryColor() : new Color(0.9f, 0.9f, 0.9f);
        var secondaryColor = isMagical ? spirit.getSecondaryColor() : new Color(0.5f, 0.5f, 0.5f);
        var builder = VFXBuilders.createWorld().setRenderType(renderType);
        final float scalar = Math.min(entityIn.age / 20f, 1f);
        RenderUtils.renderEntityTrail(poseStack, builder, entityIn.theFormer, entityIn, primaryColor, secondaryColor, scalar, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entityIn.theLatter, entityIn, primaryColor, secondaryColor, scalar, partialTicks);

        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        if (entity.isAwaitingSpawn()) {
            return;
        }
        float delta = entity.getVisualEffectScalar();
        float scale = delta * getScaleMultiplier();
        float alpha = Mth.clamp(delta * getAlphaMultiplier(), 0, 1);
        WorldVFXBuilder builder = VFXBuilders.createWorld().setRenderType(getTrailRenderType(true));
        RenderUtils.renderEntityTrail(poseStack, builder, entity.trailPointBuilder, entity, getPrimaryColor(0), getSecondaryColor(0), scale * 2f, alpha, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entity.spinningTrailPointBuilder, entity, getPrimaryColor(1), getSecondaryColor(1), scale * 2f, alpha, partialTicks);
        builder.setRenderType(getTrailRenderType(false));
        RenderUtils.renderEntityTrail(poseStack, builder, entity.trailPointBuilder, entity, getPrimaryColor(2), getSecondaryColor(2), scale, alpha, partialTicks);
        RenderUtils.renderEntityTrail(poseStack, builder, entity.spinningTrailPointBuilder, entity, getPrimaryColor(3), getSecondaryColor(3), scale, alpha, partialTicks);
        super.render(entity, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        float offsetBase = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.4f, 0.8f) * (random.nextBoolean() ? 1 : -1) + (extraData.isMirrored() ? 3.14f : 0);
        for (int i = 0; i < 8; i++) {
            ParticleEffectSpawner slash;
            if (i >= 6) {
                slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.SLASH, ColorParticleData.create(0.15f, 0.05f, 0.1f).build());
                slash.getBuilder().setRenderType(LodestoneWorldParticleRenderType.TRANSPARENT);
            } else {
                slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.SLASH, colorData);
            }
            var direction = extraData.getDirection();
            float spinOffset = extraData.getSlashRotation() + (i % 2 == 0 ? 1 : -1) * offsetBase;
            int lifeDelay = (i % 2 == 0 ? 3 : 0);
            slash.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset(spinOffset).build())
                    .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)).build())
                    .setMotion(direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.7f)))
                    .setLifeDelay(lifeDelay)
                    .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(direction));
            slash.spawnParticles();
        }
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        var direction = extraData.getDirection();
        float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
        float yaw = (float) Math.toRadians(yRot);
        Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
        for(int i = 0; i < 3; i++) {
            final Vec3 pos = positionData.getAsVector();
            for (int j = 0; j < 16; j++) {
                float spinOffset = extraData.getSlashRotation() + Easing.SINE_IN_OUT.asWeighedRandom(random, -0.5f, 0.5f) + (extraData.isMirrored() ? 3.14f : 0);
                float slashAngle = (i*0.33f+j) / 16f * (float) Math.PI * 2f;
                var slashDirection = left.scale(Math.sin(slashAngle))
                        .add(direction.scale(Math.cos(slashAngle)))
                        .normalize();
                var slashPosition = pos.add(slashDirection.scale(0.14f));

                var slash = WeaponParticleEffects.spawnSlashParticle(level, slashPosition, MalumParticles.ROUNDABOUT_SLASH, colorData);
                slash.getBuilder()
                        .setSpinData(SpinParticleData.create(0).setSpinOffset(spinOffset).build())
                        .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 2.5f, 5f)).build())
                        .setMotion(slashDirection.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.2f)).add(0, 0.2f, 0))
                        .setLifetime(12+i)
                        .setLifeDelay(i+j/4)
                        .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(slashDirection));
                slash.spawnParticles();
            }
            var slash = WeaponParticleEffects.spawnSlashParticle(level, pos, MalumParticles.ROUNDABOUT_SLASH, colorData);
            slash.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset(i * 1.57f).build())
                    .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 4.5f, 5f)).build())
                    .setLifetime(12)
                    .setLifeDelay(i*2)
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)));
            slash.spawnParticles();
        }
    }
